mapper.select:
SELECT COUNT(id)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND vender_data_code = #{venderDataCode}
  AND primary_key != #{excludedEnquiryCode}
  AND enquiry_number = #{enquiryNumber}
  AND delete_flag = 'f'

SELECT primary_key as enquiryCode, enquiry_number, enquiry_name,buyer,
seller, vender_data_code, enterprise_code as ownedEnterpriseCode,
user_code as userCode, user_name, language, payment_strategy, column_titles,
amount_title,product_detail,state,enquiry_time, data_version,sell_enquiry,son_enterprise_code,business_belong,sign_areas
FROM ${tableName}
WHERE
enterprise_code= #{currentEnterpriseCode}
AND delete_flag= 'f'

    AND enquiry_number LIKE '%'|| #{enquiryNumber} ||'%'


    AND vender_data_code = #{venderDataCode}


    AND user_code IN

        #{userCode}



    AND enquiry_time >= #{enquiryTimePre}


    AND enquiry_time <= #{enquiryTimePost}


    AND business_belong = #{businessBelong}


    ${dataScopeParams.dataScope}

ORDER BY create_time DESC

SELECT primary_key as enquiryCode, enquiry_number, enquiry_name,buyer,
seller, vender_data_code, enterprise_code as ownedEnterpriseCode,
user_code as userCode, user_name, language, payment_strategy, column_titles,
amount_title,product_detail,remark,state,enquiry_time,temp_data,
data_version,sell_enquiry,son_enterprise_code,business_belong,sign_areas
FROM ${tableName}
WHERE
enterprise_code= #{currentEnterpriseCode}
AND primary_key = #{enquiryCode}

    AND delete_flag= 'f'


    ${dataScopeParams.dataScope}

SELECT primary_key as enquiryCode, enquiry_number, enquiry_name,buyer,
seller, vender_data_code, enterprise_code as ownedEnterpriseCode,
user_code as userCode, user_name, language, payment_strategy, column_titles,
amount_title,product_detail,remark,state,enquiry_time,temp_data,
data_version,sell_enquiry,son_enterprise_code,business_belong,sign_areas
FROM ${tableName}
WHERE
enterprise_code= #{currentEnterpriseCode}
AND primary_key = #{enquiryCode}

    AND delete_flag= 'f'

mapper.update:
UPDATE ${tableName}
SET temp_data = NULL
WHERE
enterprise_code= #{model.ownedEnterpriseCode}
AND primary_key = #{model.enquiryCode}
AND temp_data IS NOT NULL

UPDATE ${tableName}
SET temp_data      = #{model.tempData},
    enquiry_number = #{number}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.enquiryCode}

UPDATE ${tableName}
SET temp_data = #{model.tempData}
WHERE
enterprise_code= #{model.ownedEnterpriseCode}
AND primary_key = #{model.enquiryCode}

mapper.delete:
DELETE FROM ${tableName}
WHERE enterprise_code = #{currentEnterpriseCode}
AND primary_key = #{enquiryCode}
AND delete_flag = 'f'
AND state = 'DRAFT'

mapper.update:
UPDATE  ${tableName}
SET
buyer = #{model.buyer},
seller = #{model.seller},
state = #{model.state},
temp_data = NULL,
data_version = #{model.dataVersion},
son_enterprise_code = #{model.sonEnterpriseCode}
WHERE
enterprise_code= #{model.ownedEnterpriseCode}
AND primary_key = #{model.enquiryCode}
AND data_version =  #{clientDataVersion}

UPDATE  ${tableName}
SET
    state = #{model.state},
    enquiry_time = #{model.enquiryTime},
    temp_data = NULL,
    data_version = #{model.dataVersion},
    son_enterprise_code = #{model.sonEnterpriseCode}
    WHERE
    enterprise_code= #{model.ownedEnterpriseCode}
  AND primary_key = #{model.enquiryCode}
  AND data_version =  #{clientDataVersion}
